import{_ as n,o as e,c as i,a0 as t}from"./chunks/framework.jwovEGr5.js";const m=JSON.parse('{"title":"Linux mint로 개발환경 옮기기","description":"","frontmatter":{},"headers":[],"relativePath":"inner-space/general/Linux-mint로-개발환경-옮기기.md","filePath":"inner-space/general/Linux-mint로-개발환경-옮기기.md"}'),o={name:"inner-space/general/Linux-mint로-개발환경-옮기기.md"};function r(l,a,_,u,c,s){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="linux-mint로-개발환경-옮기기" tabindex="-1">Linux mint로 개발환경 옮기기 <a class="header-anchor" href="#linux-mint로-개발환경-옮기기" aria-label="Permalink to &quot;Linux mint로 개발환경 옮기기&quot;">​</a></h1><p>나에게는 고민이 하나 있었다. 바로 집에 게이밍 사양 노트북이 하나 굴러다닌다는 것.</p><p>이를 메인 서버로 구축하기 위해, 나머지는 이에 접속하기 위한 (또는 게이밍) 용도로 사용하기 위해 개발환경을 구축해보자.</p><h2 id="준비물" tabindex="-1">준비물 <a class="header-anchor" href="#준비물" aria-label="Permalink to &quot;준비물&quot;">​</a></h2><ul><li>Linux mint가 깔린 게이밍 노트북</li></ul><h2 id="_1-linux-mint로-환경-옮기기" tabindex="-1">1. Linux mint로 환경 옮기기 <a class="header-anchor" href="#_1-linux-mint로-환경-옮기기" aria-label="Permalink to &quot;1. Linux mint로 환경 옮기기&quot;">​</a></h2><p>일단 git에 올라가 있는 것을 제외하고는 icloud에서의 접근성이 더 좋으므로, Documents들을 icloud에 옮기자.</p><p><code>Documents</code></p><p>기존에 이용했던 맥북의 documents나 기본 패키지들은 정리하도록 하자.</p><p>또한 UTM을 이용해 가지고 놀던 리눅스들도 정리하도록 하자. (리눅스 마스터를 위한 rocky는 나중에 따로 고민해보자)</p><p>이제 맥미니와 맥북이 가벼워졌다.</p><h2 id="_2-wake-on-lan-설정하기" tabindex="-1">2. Wake-on-LAN 설정하기 <a class="header-anchor" href="#_2-wake-on-lan-설정하기" aria-label="Permalink to &quot;2. Wake-on-LAN 설정하기&quot;">​</a></h2><p>기존에 귀하디 귀하신 닌텐도 스위치가 쓰던 랜선을 뽑아 노트북에 연결한 뒤, Wake-on-LAN을 설정해보자. 이는 랜선 연결을 이용해 컴퓨터를 원격으로 끄고 켤 수 있는 기능이다. 다만 보안을 위해 Tailscale은 필수이다.</p>',13)])])}const d=n(o,[["render",r]]);export{m as __pageData,d as default};
